//! `Accept` and `create_view` against a real prikk (RFC 002 D-4; handoff 002 T4): a wiki created through the
//! signer's own entry points (keys generated by prikk, sealed in the key store, the first change committed),
//! then acceptances, refusals, failures and a killed server. Self-skips with a visible line when prikk is not
//! on `PATH`; the happy path runs confined (bubblewrap) as well as unconfined where bubblewrap works.
//!
//! Failures after `commit` need a prikk that fails on cue, and the kill test needs one that waits: a
//! **stand-in** script passes every call to the real prikk except the verb a control file names. The stand-in
//! runs only unconfined (a confined prikk sees nothing but `/usr` and itself).
#![allow(clippy::expect_used, clippy::unwrap_used)]

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use inklkunn_prikk::sandbox::probe_bwrap;
use inklkunn_prikk::{Admission, Point, PrikkCli, Sandbox, Storage};
use inklkunn_signer::message::{Actor, BlockId, Message, Summary, SystemLabel};
use inklkunn_signer::{
    Accept, AcceptError, AcceptanceLedger, AcceptanceToken, ExpectedMessage, LedgerError,
    PreparedChange, PreparedFile, RepositoryBootstrap, Signer, SignerConfig, SignerError,
    Unconfirmed, ViewCreationAct, ViewCreationFacts,
};
use inklkunn_store::{AccountId, DisplayName, ProposalId, RootLayout, WikiId};

static NULL: serde_json::Value = serde_json::Value::Null;

/// A field of a JSON value, `null` when absent (no indexing that could panic).
fn field<'a>(v: &'a serde_json::Value, key: &str) -> &'a serde_json::Value {
    v.get(key).unwrap_or(&NULL)
}

const SECRET: &str = "an operator secret for the integration tests, long enough";

fn real_prikk() -> Option<PathBuf> {
    std::env::var_os("PATH").and_then(|p| {
        std::env::split_paths(&p)
            .map(|d| d.join("prikk"))
            .find(|c| c.is_file())
    })
}

/// A directory removed when dropped (including one a test left unwritable).
struct Dir(PathBuf);

impl Drop for Dir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn dir_under(base: &Path, tag: &str) -> Dir {
    let p = base.join(format!("inklkunn-it-{}-{tag}", std::process::id()));
    let _ = std::fs::remove_dir_all(&p);
    std::fs::create_dir_all(&p).expect("dir");
    // A seed base must be private to the user (the signer refuses one others can write to).
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o700)).expect("private");
    Dir(p)
}

#[derive(Default)]
struct Ledger {
    pending: Mutex<HashMap<String, ExpectedMessage>>,
    views: Mutex<HashMap<String, ViewCreationFacts>>,
}

impl Ledger {
    fn set(&self, token: &AcceptanceToken, expected: ExpectedMessage) {
        self.pending
            .lock()
            .unwrap()
            .insert(token.as_str().to_owned(), expected);
    }
}

impl AcceptanceLedger for Ledger {
    fn pending(&self, token: &AcceptanceToken) -> Result<Option<ExpectedMessage>, LedgerError> {
        Ok(self.pending.lock().unwrap().get(token.as_str()).cloned())
    }

    fn view_creation(
        &self,
        act: &ViewCreationAct,
    ) -> Result<Option<ViewCreationFacts>, LedgerError> {
        Ok(self.views.lock().unwrap().get(act.as_str()).cloned())
    }
}

/// A wiki with a signer over it.
struct Fixture {
    _tmp: Dir,
    shm: Dir,
    ctl: PathBuf,
    root: RootLayout,
    key_dir: PathBuf,
    secret_file: PathBuf,
    wiki: WikiId,
    repo: PathBuf,
    ledger: Arc<Ledger>,
    signer: Signer,
    prikk: PathBuf,
    first_block: String,
    proposer: Actor,
    acceptor: Actor,
}

fn config(f: &Fixtureless, prikk: &Path, sandbox: Sandbox) -> SignerConfig {
    let mut cfg = SignerConfig::new(
        prikk,
        sandbox,
        f.root.clone(),
        &f.key_dir,
        &f.secret_file,
        &f.shm,
    );
    cfg.cheap_derivation = true;
    cfg
}

/// What a signer needs before there is a signer.
struct Fixtureless {
    root: RootLayout,
    key_dir: PathBuf,
    secret_file: PathBuf,
    shm: PathBuf,
}

fn account(name: &str) -> Actor {
    Actor::Account {
        id: AccountId::new(),
        name: DisplayName::new(name).expect("name"),
    }
}

/// The stand-in `prikk`: every call goes to the real one unless a control file says otherwise.
fn write_standin(ctl: &Path, real: &Path) -> PathBuf {
    let script = format!(
        r#"#!/bin/sh
CTL="{ctl}"
REAL="{real}"
verb="$1"
echo "$verb" >> "$CTL/calls.log"
if [ -e "$CTL/probe-$verb" ]; then
  {{
    echo "== $verb $2"
    echo "vars: $(env | sed -n 's/^\(PRIKK_[A-Z_]*\)=.*/\1/p' | sort | tr '\n' ' ')"
    for v in PRIKK_AUTHOR_SEED_FILE PRIKK_MAINTAINER_SEED_FILE; do
      f="$(printenv "$v")"
      if [ -n "$f" ]; then
        d="$(dirname "$f")"
        echo "$v dir holds: $(ls -A "$d" | tr '\n' ' ')"
        stat -c 'dir=%a' "$d"
        stat -c 'file=%a' "$f"
        cat "$f"
      fi
    done
  }} >> "$CTL/probe.log" 2>&1
fi
if [ -e "$CTL/fail-$verb" ]; then echo "error: precondition not met: injected failure of $verb" >&2; exit 1; fi
if [ -e "$CTL/failafter-$verb" ]; then
  n="$(cat "$CTL/failafter-$verb")"; c="$(cat "$CTL/count-$verb" 2>/dev/null || echo 0)"
  echo "$((c + 1))" > "$CTL/count-$verb"
  if [ "$c" -ge "$n" ]; then echo "error: precondition not met: injected failure of $verb" >&2; exit 1; fi
fi
if [ -e "$CTL/die-$verb" ]; then
  case "$(cat "$CTL/die-$verb")" in
    abort) echo "memory allocation of 629145648 bytes failed" >&2; exit 134 ;;
    loader) echo "error while loading shared libraries: cannot allocate TLS" >&2; exit 127 ;;
    segv) kill -SEGV $$ ;;
    bwrap) echo "Out of memory" >&2; exit 1 ;;
  esac
fi
if [ -e "$CTL/say-$verb" ]; then cat "$CTL/say-$verb"; exit 0; fi
if [ -e "$CTL/lockseeds-$verb" ]; then chmod 0500 "$(dirname "${{PRIKK_AUTHOR_SEED_FILE:-$PRIKK_MAINTAINER_SEED_FILE}}")"; fi
if [ -e "$CTL/report-$verb" ]; then cat "$CTL/report-$verb"; exit 1; fi
if [ -e "$CTL/block-$verb" ]; then : > "$CTL/blocked-$verb"; sleep 20; fi
exec "$REAL" "$@"
"#,
        ctl = ctl.display(),
        real = real.display()
    );
    let path = ctl.join("prikk");
    std::fs::write(&path, script).expect("stand-in");
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).expect("chmod");
    path
}

fn shm_base() -> Option<PathBuf> {
    let p = PathBuf::from("/dev/shm");
    if p.is_dir() {
        Some(p)
    } else {
        println!("skipping: no /dev/shm here");
        None
    }
}

/// Build a wiki: keys, repository, one sealed first change. `use_standin` puts the stand-in prikk (and so
/// the unconfined policy) in front of the real one.
fn fixture(tag: &str, sandbox: Sandbox, use_standin: bool) -> Option<Fixture> {
    let real = real_prikk()?;
    let shm_base = shm_base()?;
    let tmp = dir_under(&std::env::temp_dir(), tag);
    let shm = dir_under(&shm_base, tag);
    let ctl = tmp.0.join("ctl");
    std::fs::create_dir_all(&ctl).unwrap();
    let prikk = if use_standin {
        write_standin(&ctl, &real)
    } else {
        real.clone()
    };
    let root = RootLayout::new(tmp.0.join("root"));
    let key_dir = tmp.0.join("keys");
    let secret_file = tmp.0.join("secret");
    std::fs::write(&secret_file, format!("{SECRET}\n")).unwrap();
    let pre = Fixtureless {
        root: root.clone(),
        key_dir: key_dir.clone(),
        secret_file: secret_file.clone(),
        shm: shm.0.clone(),
    };
    let ledger = Arc::new(Ledger::default());
    let signer = Signer::open_creating_store(config(&pre, &prikk, sandbox), ledger.clone())
        .expect("signer opens");
    let wiki = WikiId::new();
    let repo = root.prepare(&wiki).expect("directories");
    let ids = signer
        .create_repository(&repo, &inklkunn_signer::KeyAuthority::for_tests())
        .expect("repository and keys");
    assert_eq!(ids.author, format!("inklkunn-{wiki}-author"));
    assert_eq!(ids.maintainer, format!("inklkunn-{wiki}-maintainer"));
    for (path, text) in [
        (
            "wiki-bundle.yaml",
            "format: portable-wiki-bundle\nversion: '0.4'\n",
        ),
        ("pages/Home.md", "---\ntitle: Home\n---\n\nHello.\n"),
        ("pages/Edit.md", "---\ntitle: Edit\n---\n\nbefore\n"),
        (
            "pages/Rename Me.md",
            "---\ntitle: Rename Me\n---\n\nold name\n",
        ),
        ("pages/Remove.md", "---\ntitle: Remove\n---\n\nbye\n"),
    ] {
        let p = repo.join(path);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, text).unwrap();
    }
    let first = Message::system(
        Summary::from_text("Create the wiki").unwrap(),
        SystemLabel::inklkunn(),
    );
    let sealed = signer
        .commit_and_seal(&repo, &first.to_text())
        .expect("the first change");
    Some(Fixture {
        _tmp: tmp,
        shm,
        ctl,
        root,
        key_dir,
        secret_file,
        wiki,
        repo,
        ledger,
        signer,
        prikk,
        first_block: sealed.block_id,
        proposer: account("Aiko Tanaka"),
        acceptor: account("Ben (maintainer)"),
    })
}

fn policies() -> Vec<Sandbox> {
    if probe_bwrap(std::ffi::OsStr::new("bwrap")).is_ok() {
        vec![Sandbox::default(), Sandbox::Unconfined]
    } else {
        println!("skipping: bubblewrap cannot confine a process here; running unconfined");
        vec![Sandbox::Unconfined]
    }
}

fn file(path: &str, content: Option<&str>) -> PreparedFile {
    PreparedFile {
        path: PathBuf::from(path),
        content: content.map(|c| c.as_bytes().to_vec()),
    }
}

/// A change, the token for it, and the record the ledger will hold for it.
struct Prepared {
    token: AcceptanceToken,
    change: PreparedChange,
    expected: ExpectedMessage,
    proposal: ProposalId,
}

impl Fixture {
    fn prepare(
        &self,
        view: &str,
        files: Vec<PreparedFile>,
        renames: Vec<(&str, &str)>,
    ) -> Prepared {
        let proposal = ProposalId::new();
        let base = BlockId::new(&self.first_block).unwrap();
        let message = Message::proposal(
            Summary::from_text("Improve the wiki").unwrap(),
            proposal.clone(),
            self.proposer.clone(),
            self.acceptor.clone(),
            base.clone(),
        )
        .unwrap();
        let token = AcceptanceToken::new(format!("acceptance-{proposal}"));
        let change = PreparedChange {
            files,
            renames: renames
                .into_iter()
                .map(|(a, b)| (PathBuf::from(a), PathBuf::from(b)))
                .collect(),
            message: message.to_text(),
        };
        let expected = ExpectedMessage {
            wiki: self.wiki.clone(),
            view: view.to_owned(),
            kind: message.kind(),
            proposal: Some(proposal.clone()),
            proposed_by: self.proposer.clone(),
            accepted_by: self.acceptor.clone(),
            base: Some(base),
            imported_from: None,
            change_digest: change.digest(),
        };
        self.ledger.set(&token, expected.clone());
        Prepared {
            token,
            change,
            expected,
            proposal,
        }
    }

    fn storage(&self, sandbox: Sandbox) -> PrikkCli {
        PrikkCli::open(
            self.prikk.as_os_str(),
            sandbox,
            Admission::new(1 << 30, 64 << 20, Duration::from_millis(200)),
        )
        .expect("prikk at the floor")
    }

    fn history_len(&self, view: &str) -> usize {
        self.storage(Sandbox::Unconfined)
            .history(&self.repo, &Point::View(view.to_owned()), None)
            .map(|h| h.blocks.len())
            .unwrap_or(0)
    }

    fn read(&self, view: &str, path: &str) -> Option<String> {
        self.storage(Sandbox::Unconfined)
            .read(&self.repo, &Point::View(view.to_owned()), path, 1 << 20)
            .ok()
            .map(|b| String::from_utf8_lossy(&b).into_owned())
    }

    /// Run a prikk read in the repository, as the operator would.
    fn prikk_json(&self, args: &[&str]) -> serde_json::Value {
        let out = Command::new(&self.prikk)
            .args(args)
            .current_dir(&self.repo)
            .output()
            .expect("prikk runs");
        serde_json::from_slice(&out.stdout).unwrap_or(serde_json::Value::Null)
    }

    fn worktree_clean(&self) -> bool {
        self.prikk_json(&["worktree-status", "--format", "json"])
            .get("clean")
            == Some(&serde_json::Value::Bool(true))
    }

    fn queue_count(&self) -> u64 {
        self.prikk_json(&["status", "--format", "json"])
            .pointer("/queue/count")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(u64::MAX)
    }

    /// The newest block of a view, by `prikk log`.
    fn tip_block(&self, view: &str) -> String {
        self.prikk_json(&["log", "--ref", view, "--limit", "1", "--format", "json"])
            .pointer("/blocks/0/block_id")
            .and_then(serde_json::Value::as_str)
            .expect("a block")
            .to_owned()
    }

    fn seed_dirs(&self) -> Vec<PathBuf> {
        std::fs::read_dir(&self.shm.0)
            .map(|it| {
                it.flatten()
                    .map(|e| e.path())
                    .filter(|p| {
                        p.file_name()
                            .is_some_and(|n| n.to_string_lossy().starts_with("inklkunn-seeds-"))
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

    fn control(&self, name: &str) {
        std::fs::write(self.ctl.join(name), "").unwrap();
    }

    fn uncontrol(&self, name: &str) {
        let _ = std::fs::remove_file(self.ctl.join(name));
    }
}

const MAIN: &str = "heads/main";

#[test]
fn an_accepted_proposal_is_committed_sealed_attributed_and_verified_and_leaves_no_seed() {
    for (n, sandbox) in policies().into_iter().enumerate() {
        let Some(f) = fixture(&format!("happy-{n}"), sandbox.clone(), false) else {
            println!("skipping: prikk not on PATH");
            return;
        };
        let p = f.prepare(
            MAIN,
            vec![
                file("pages/Edit.md", Some("---\ntitle: Edit\n---\n\nafter\n")),
                file("pages/New.md", Some("new page\n")),
            ],
            vec![],
        );
        let before = f.history_len(MAIN);
        let sealed = f
            .signer
            .accept(&f.wiki, MAIN, &p.token, &p.change)
            .expect("accepted");
        // The history gained exactly one change, whose message is what was composed, byte for byte.
        let storage = f.storage(sandbox);
        let history = storage
            .history(&f.repo, &Point::View(MAIN.into()), None)
            .unwrap();
        assert_eq!(history.blocks.len(), before + 1);
        let tip = history.blocks.first().unwrap();
        assert_eq!(tip.block_id, sealed.block_id);
        assert_eq!(
            tip.patch_messages.first().unwrap().message,
            p.change.message
        );
        assert_eq!(
            Message::parse(&tip.patch_messages.first().unwrap().message)
                .unwrap()
                .proposal_id(),
            Some(&p.proposal)
        );
        assert!(!sealed.patch_ids.is_empty());
        // The content is there, the repository verifies by prikk's own check, the worktree is clean, and
        // the decrypted seeds are gone.
        assert_eq!(
            f.read(MAIN, "pages/Edit.md").unwrap(),
            "---\ntitle: Edit\n---\n\nafter\n"
        );
        assert_eq!(f.read(MAIN, "pages/New.md").unwrap(), "new page\n");
        assert!(storage.verify(&f.repo).unwrap().verdict.ok);
        assert!(f.worktree_clean());
        assert_eq!(f.queue_count(), 0);
        assert!(f.seed_dirs().is_empty(), "{:?}", f.seed_dirs());
    }
}

#[test]
fn renames_edits_and_removals_land_as_one_change_with_the_rename_declared() {
    let Some(f) = fixture("mixed", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(
        MAIN,
        vec![
            file(
                "pages/Renamed Page.md",
                Some(
                    "---\ntitle: Renamed Page\naliases: [Rename Me]\n---\n\nnew name, new words\n",
                ),
            ),
            file("pages/Remove.md", None),
            file("pages/Deep/Er/Page.md", Some("deep\n")),
        ],
        vec![("pages/Rename Me.md", "pages/Renamed Page.md")],
    );
    let before = f.history_len(MAIN);
    f.signer
        .accept(&f.wiki, MAIN, &p.token, &p.change)
        .expect("accepted");
    assert_eq!(
        f.history_len(MAIN),
        before + 1,
        "one acceptance, one change"
    );
    assert!(f.read(MAIN, "pages/Rename Me.md").is_none());
    assert!(f.read(MAIN, "pages/Remove.md").is_none());
    assert!(
        f.read(MAIN, "pages/Renamed Page.md")
            .unwrap()
            .contains("new name, new words")
    );
    assert_eq!(f.read(MAIN, "pages/Deep/Er/Page.md").unwrap(), "deep\n");
    // prikk recorded the move as a rename (identity survives), not as a delete and a create.
    let storage = f.storage(Sandbox::Unconfined);
    let history = storage
        .history(&f.repo, &Point::View(MAIN.into()), None)
        .unwrap();
    let (new, old) = (
        history.blocks.first().unwrap(),
        history.blocks.get(1).unwrap(),
    );
    let diff = storage
        .diff(
            &f.repo,
            &Point::Block(old.block_id.clone()),
            &Point::Block(new.block_id.clone()),
            &[],
        )
        .unwrap();
    let renamed = diff
        .entries
        .iter()
        .find(|e| e.path == "pages/Renamed Page.md")
        .expect("entry");
    assert_eq!(renamed.status, "renamed", "{diff:?}");
    assert!(storage.verify(&f.repo).unwrap().verdict.ok);
    assert!(f.worktree_clean());
}

#[test]
fn a_token_that_is_not_pending_for_this_wiki_and_view_is_refused_before_anything_happens() {
    let Some(f) = fixture("notpending", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(MAIN, vec![file("pages/X.md", Some("x\n"))], vec![]);
    let before = f.history_len(MAIN);
    let calls = || {
        std::fs::read_to_string(f.ctl.join("calls.log"))
            .unwrap_or_default()
            .lines()
            .count()
    };
    let calls_before = calls();
    // An unknown token; a record for another wiki; a record for another view.
    assert_eq!(
        f.signer
            .accept(&f.wiki, MAIN, &AcceptanceToken::new("nope"), &p.change),
        Err(AcceptError::NotPending)
    );
    let mut other_wiki = p.expected.clone();
    other_wiki.wiki = WikiId::new();
    f.ledger.set(&p.token, other_wiki);
    assert_eq!(
        f.signer.accept(&f.wiki, MAIN, &p.token, &p.change),
        Err(AcceptError::NotPending)
    );
    let mut other_view = p.expected.clone();
    other_view.view = "heads/draft".into();
    f.ledger.set(&p.token, other_view);
    assert_eq!(
        f.signer.accept(&f.wiki, MAIN, &p.token, &p.change),
        Err(AcceptError::NotPending)
    );
    // A view that is not a view.
    assert!(matches!(
        f.signer.accept(&f.wiki, "main", &p.token, &p.change),
        Err(AcceptError::Refused(_))
    ));
    // Nothing happened: no prikk call was made by any of them, no seed was decrypted, no file written.
    assert_eq!(
        calls(),
        calls_before,
        "the guard runs before prikk is touched"
    );
    assert!(f.seed_dirs().is_empty());
    assert_eq!(f.history_len(MAIN), before);
    assert!(!f.repo.join("pages/X.md").exists());
    assert!(f.worktree_clean());
}

#[test]
fn a_message_that_names_another_proposal_acceptor_base_or_kind_is_refused() {
    let Some(f) = fixture("mismatch", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(MAIN, vec![file("pages/X.md", Some("x\n"))], vec![]);
    let calls_before = std::fs::read_to_string(f.ctl.join("calls.log"))
        .unwrap_or_default()
        .lines()
        .count();
    let compose =
        |proposal: &ProposalId, proposer: &Actor, acceptor: &Actor, base: &str, rollback: bool| {
            let (summary, base) = (
                Summary::from_text("Improve the wiki").unwrap(),
                BlockId::new(base).unwrap(),
            );
            if rollback {
                Message::rollback(
                    summary,
                    proposal.clone(),
                    proposer.clone(),
                    acceptor.clone(),
                    base,
                )
            } else {
                Message::proposal(
                    summary,
                    proposal.clone(),
                    proposer.clone(),
                    acceptor.clone(),
                    base,
                )
            }
            .unwrap()
            .to_text()
        };
    let stranger = account("Mallory");
    let other_base = "cd".repeat(32);
    let cases = [
        (
            "another proposal",
            compose(
                &ProposalId::new(),
                &f.proposer,
                &f.acceptor,
                &f.first_block,
                false,
            ),
        ),
        (
            "another proposer",
            compose(&p.proposal, &stranger, &f.acceptor, &f.first_block, false),
        ),
        (
            "another acceptor",
            compose(&p.proposal, &f.proposer, &stranger, &f.first_block, false),
        ),
        (
            "another base",
            compose(&p.proposal, &f.proposer, &f.acceptor, &other_base, false),
        ),
        (
            "another kind",
            compose(&p.proposal, &f.proposer, &f.acceptor, &f.first_block, true),
        ),
        ("not a message", "Improve the wiki".to_owned()),
        (
            "a message with an extra trailer",
            format!("{}Signed-Off-By: x\n", p.change.message),
        ),
        (
            "a system message",
            Message::system(Summary::from_text("s").unwrap(), SystemLabel::inklkunn()).to_text(),
        ),
    ];
    for (what, message) in cases {
        let change = PreparedChange {
            message,
            ..p.change.clone()
        };
        assert_eq!(
            f.signer.accept(&f.wiki, MAIN, &p.token, &change),
            Err(AcceptError::MessageMismatch),
            "{what}"
        );
    }
    // The summary is the proposer's words, not part of the binding: a different one is accepted.
    let reworded = Message::proposal(
        Summary::from_text("A different summary of the same change").unwrap(),
        p.proposal.clone(),
        f.proposer.clone(),
        f.acceptor.clone(),
        BlockId::new(&f.first_block).unwrap(),
    )
    .unwrap();
    let calls_after = std::fs::read_to_string(f.ctl.join("calls.log"))
        .unwrap_or_default()
        .lines()
        .count();
    assert_eq!(
        calls_after, calls_before,
        "every mismatch was refused before prikk was touched"
    );
    let change = PreparedChange {
        message: reworded.to_text(),
        ..p.change.clone()
    };
    assert!(f.signer.accept(&f.wiki, MAIN, &p.token, &change).is_ok());
}

#[test]
fn a_change_that_breaks_a_rule_is_refused_whole_and_touches_nothing() {
    let Some(f) = fixture("rules", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let before = f.history_len(MAIN);
    for (what, files, renames) in [
        (
            "a path inside .prikk",
            vec![
                file("pages/Fine.md", Some("ok")),
                file(".prikk/config", Some("x")),
            ],
            vec![],
        ),
        (
            "a non-ASCII path",
            vec![file("pages/日本語.md", Some("x"))],
            vec![],
        ),
        (
            "a path outside the roots",
            vec![file("README.md", Some("x"))],
            vec![],
        ),
        (
            "a traversal",
            vec![file("pages/../../etc/x", Some("x"))],
            vec![],
        ),
        (
            "an absolute path",
            vec![file("/etc/passwd", Some("x"))],
            vec![],
        ),
        (
            "a plain-spelling violation",
            vec![file("pages/./Dot.md", Some("x"))],
            vec![],
        ),
        (
            "a path twice",
            vec![file("pages/A.md", Some("a")), file("pages/A.md", Some("b"))],
            vec![],
        ),
        (
            "a chain of renames",
            vec![],
            vec![
                ("pages/Edit.md", "pages/B.md"),
                ("pages/B.md", "pages/C.md"),
            ],
        ),
        ("an empty change", vec![], vec![]),
    ] {
        let p = f.prepare(MAIN, files, renames);
        let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
        assert!(matches!(r, Err(AcceptError::Refused(_))), "{what}: {r:?}");
        assert!(f.worktree_clean(), "{what}");
        assert!(
            f.seed_dirs().is_empty() || f.seed_dirs().len() == 1,
            "{what}"
        );
    }
    assert_eq!(f.history_len(MAIN), before);
    assert!(f.read(MAIN, "pages/Fine.md").is_none());
    assert!(
        !f.repo.join("pages/Fine.md").exists(),
        "a valid file in a refused change was never written"
    );
}

#[test]
fn a_prikk_refusal_at_commit_puts_the_worktree_back_exactly() {
    let Some(f) = fixture("restore", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    // Rename + edit + remove + a new directory, then prikk refuses the commit.
    let p = f.prepare(
        MAIN,
        vec![
            file(
                "pages/Renamed Page.md",
                Some("---\ntitle: Renamed Page\n---\n\nrewritten\n"),
            ),
            file("pages/Edit.md", Some("edited\n")),
            file("pages/Remove.md", None),
            file("pages/Fresh/Dir/New.md", Some("new\n")),
        ],
        vec![("pages/Rename Me.md", "pages/Renamed Page.md")],
    );
    let original_edit = std::fs::read(f.repo.join("pages/Edit.md")).unwrap();
    let original_old = std::fs::read(f.repo.join("pages/Rename Me.md")).unwrap();
    let original_removed = std::fs::read(f.repo.join("pages/Remove.md")).unwrap();
    f.control("fail-commit");
    let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
    assert!(
        matches!(&r, Err(AcceptError::Refused(m)) if m.contains("injected")),
        "{r:?}"
    );
    // The worktree is the tip again: files, the rename, the removal and the new directories.
    assert_eq!(
        std::fs::read(f.repo.join("pages/Edit.md")).unwrap(),
        original_edit
    );
    assert_eq!(
        std::fs::read(f.repo.join("pages/Rename Me.md")).unwrap(),
        original_old
    );
    assert_eq!(
        std::fs::read(f.repo.join("pages/Remove.md")).unwrap(),
        original_removed
    );
    assert!(!f.repo.join("pages/Renamed Page.md").exists());
    assert!(!f.repo.join("pages/Fresh").exists());
    assert!(
        f.worktree_clean(),
        "prikk itself says nothing is left (no change, no declared rename)"
    );
    assert_eq!(f.queue_count(), 0);
    assert!(f.seed_dirs().is_empty());
    // And the next acceptance works.
    f.uncontrol("fail-commit");
    let again = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    assert!(
        f.signer
            .accept(&f.wiki, MAIN, &again.token, &again.change)
            .is_ok()
    );
}

#[test]
fn a_failure_after_commit_is_queued_leaves_one_queued_patch_and_blocks_the_next_acceptance() {
    let Some(f) = fixture("incomplete", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    let before = f.history_len(MAIN);
    f.control("fail-seal");
    let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
    assert!(
        matches!(&r, Err(AcceptError::Queued { step: "seal", .. })),
        "{r:?}"
    );
    // Exactly one patch is queued for recovery, nothing was sealed, and the seeds are gone.
    assert_eq!(f.queue_count(), 1);
    assert_eq!(f.history_len(MAIN), before);
    assert!(f.seed_dirs().is_empty());
    // The queued patch carries the message, so recovery can match it to its intent.
    let queued = f.prikk_json(&["status", "--format", "json"]);
    assert_eq!(
        queued
            .pointer("/queue/patches/0/message")
            .and_then(serde_json::Value::as_str),
        Some(p.change.message.as_str())
    );
    // A second acceptance is refused until recovery has run: it would otherwise seal both patches together.
    f.uncontrol("fail-seal");
    let next = f.prepare(MAIN, vec![file("pages/Home.md", Some("home\n"))], vec![]);
    let r = f.signer.accept(&f.wiki, MAIN, &next.token, &next.change);
    assert!(
        matches!(&r, Err(AcceptError::Refused(m)) if m.contains("unsealed")),
        "{r:?}"
    );
    assert_eq!(f.queue_count(), 1);
}

