#[test]
fn the_guard_answers_before_the_signer_so_much_as_tries_to_make_a_seed_directory() {
    let Some(f) = fixture("guard-first", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    use std::os::unix::fs::PermissionsExt;
    // A seed base nothing can be made in: if the signer decrypted before it checked, the answer would be an
    // I/O failure instead of the guard's.
    std::fs::set_permissions(&f.shm.0, std::fs::Permissions::from_mode(0o500)).unwrap();
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    let stranger = AcceptanceToken::new("acceptance-never-recorded".to_owned());
    let r = f.signer.accept(&f.wiki, MAIN, &stranger, &p.change);
    assert_eq!(r, Err(AcceptError::NotPending));
    // And with a valid token the same base is what stops it, which proves the base really was unusable.
    let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
    assert!(matches!(&r, Err(AcceptError::Unavailable(_))), "{r:?}");
    std::fs::set_permissions(&f.shm.0, std::fs::Permissions::from_mode(0o700)).unwrap();
}

/// What each verb of the write sequence can see, per verb, from the inside (a stand-in that lists its own
/// environment and the directory its seed variable names): `commit` the author seed alone, `seal` and `branch
/// create` the maintainer seed alone, and `init`, `trust`, `mv`, `branch switch` nothing (RFC 002 C-1a, C-1c).
#[test]
fn each_write_verb_sees_only_the_seed_it_signs_with_and_a_verb_that_signs_nothing_sees_none() {
    let Some(f) = fixture("verb-visibility", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    for verb in ["init", "trust", "mv", "branch", "commit", "seal"] {
        f.control(&format!("probe-{verb}"));
    }
    // A second wiki: `init` and `trust` run with the probes on.
    let other = WikiId::new();
    let other_repo = f.root.prepare(&other).unwrap();
    f.signer
        .create_repository(&other_repo, &inklkunn_signer::KeyAuthority::for_tests())
        .expect("a second wiki");
    // A view, then an acceptance on it (a `branch switch` to it) that renames a page (an `mv`).
    f.ledger.views.lock().unwrap().insert(
        "act-v".into(),
        ViewCreationFacts {
            wiki: f.wiki.clone(),
            name: "heads/draft".into(),
            from: MAIN.into(),
        },
    );
    f.signer
        .create_view(&f.wiki, "heads/draft", MAIN, &ViewCreationAct::new("act-v"))
        .expect("view");
    let p = f.prepare(
        "heads/draft",
        vec![file("pages/Edit.md", Some("edited\n"))],
        vec![("pages/Rename Me.md", "pages/Renamed.md")],
    );
    f.signer
        .accept(&f.wiki, "heads/draft", &p.token, &p.change)
        .expect("accepted");

    let probe = std::fs::read_to_string(f.ctl.join("probe.log")).unwrap();
    let blocks: Vec<&str> = probe.split("== ").skip(1).collect();
    let of = |head: &str| -> &str {
        blocks
            .iter()
            .copied()
            .find(|b| b.starts_with(head))
            .unwrap_or_else(|| panic!("`{head}` was never probed: {probe}"))
    };
    let no_seed = |head: &str| {
        let b = of(head);
        assert!(
            b.contains("vars: \n"),
            "{head} was handed key variables: {b}"
        );
        assert!(!b.contains("dir holds"), "{head} saw a seed directory: {b}");
    };
    no_seed("init");
    no_seed("trust");
    no_seed("mv");
    no_seed("branch switch");
    let author_only = |head: &str| {
        let b = of(head);
        assert!(
            b.contains("vars: PRIKK_AUTHOR_KEY_ID PRIKK_AUTHOR_SEED_FILE \n")
                && b.contains("dir holds: author.seed \n"),
            "{head}: {b}"
        );
    };
    let maintainer_only = |head: &str| {
        let b = of(head);
        assert!(
            b.contains("vars: PRIKK_MAINTAINER_KEY_ID PRIKK_MAINTAINER_SEED_FILE \n")
                && b.contains("dir holds: maintainer.seed \n"),
            "{head}: {b}"
        );
    };
    author_only("commit");
    maintainer_only("seal");
    maintainer_only("branch create");
    assert!(f.seed_dirs().is_empty(), "every seed directory was removed");
}

#[test]
fn the_seeds_exist_only_while_prikk_runs_and_are_where_the_signer_says() {
    let Some(f) = fixture("seedlife", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    f.control("probe-commit");
    f.control("probe-seal");
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    assert!(f.seed_dirs().is_empty(), "before the call there is nothing");
    f.signer
        .accept(&f.wiki, MAIN, &p.token, &p.change)
        .expect("accepted");
    assert!(f.seed_dirs().is_empty(), "after the call there is nothing");
    let probe =
        std::fs::read_to_string(f.ctl.join("probe.log")).expect("the stand-in saw the seeds");
    for verb in ["commit", "seal"] {
        assert!(probe.contains(&format!("== {verb}")), "{probe}");
    }
    // During: each call saw a private directory holding exactly the one seed it signs with, readable only by
    // its owner: `commit` the author's, `seal` the maintainer's.
    let block = |verb: &str| -> &str {
        probe
            .split("== ")
            .find(|b| b.starts_with(verb))
            .unwrap_or_else(|| panic!("no probe of {verb}: {probe}"))
    };
    let commit = block("commit");
    assert!(
        commit.contains("vars: PRIKK_AUTHOR_KEY_ID PRIKK_AUTHOR_SEED_FILE \n")
            && commit.contains("dir holds: author.seed \n")
            && !commit.contains("maintainer"),
        "{commit}"
    );
    let seal = block("seal");
    assert!(
        seal.contains("vars: PRIKK_MAINTAINER_KEY_ID PRIKK_MAINTAINER_SEED_FILE \n")
            && seal.contains("dir holds: maintainer.seed \n")
            && !seal.contains("author"),
        "{seal}"
    );
    for b in [commit, seal] {
        assert!(b.contains("dir=700") && b.contains("file=600"), "{b}");
    }
    // What prikk read there is a seed: 64 hex characters, and the signer's error texts never carry it.
    let seeds: Vec<&str> = probe
        .lines()
        .filter(|l| l.len() == 64 && l.bytes().all(|b| b.is_ascii_hexdigit()))
        .collect();
    assert_eq!(seeds.len(), 2, "{probe}");
    let key_file = std::fs::read_to_string(f.key_dir.join(format!("{}.key.json", f.wiki))).unwrap();
    for seed in &seeds {
        assert!(!key_file.contains(seed), "a seed is in the sealed record");
    }
}

#[test]
fn no_error_text_ever_carries_a_seed_the_secret_or_the_seed_directory() {
    let Some(f) = fixture("grep", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    f.control("probe-commit");
    f.control("probe-seal");
    f.control("fail-seal");
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    let mut shown = vec![format!("{:?}", f.signer)];
    let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
    shown.push(format!("{r:?}"));
    shown.push(r.unwrap_err().to_string());
    let probe = std::fs::read_to_string(f.ctl.join("probe.log")).unwrap();
    let seeds: Vec<String> = probe
        .lines()
        .filter(|l| l.len() == 64 && l.bytes().all(|b| b.is_ascii_hexdigit()))
        .map(str::to_owned)
        .collect();
    assert!(seeds.len() >= 2);
    let dir_names: Vec<String> = probe
        .lines()
        .filter(|l| l.starts_with("inklkunn-seeds-"))
        .map(str::to_owned)
        .collect();
    for e in [
        f.signer
            .accept(&f.wiki, MAIN, &AcceptanceToken::new("x"), &p.change)
            .unwrap_err()
            .to_string(),
        format!("{:?}", f.signer.key_status(&f.wiki).unwrap()),
        format!("{:?}", f.signer.key_status(&WikiId::new()).unwrap_err()),
        f.signer
            .create_repository(&f.repo, &inklkunn_signer::KeyAuthority::for_tests())
            .unwrap_err()
            .to_string(),
    ] {
        shown.push(e);
    }
    for text in &shown {
        for seed in &seeds {
            assert!(!text.contains(seed), "a seed is in: {text}");
        }
        assert!(!text.contains(SECRET), "the secret is in: {text}");
        assert!(
            !text.contains("/dev/shm"),
            "the seed directory is named in: {text}"
        );
        for name in &dir_names {
            assert!(!text.contains(name.as_str()), "{text}");
        }
    }
}

#[test]
fn a_killed_server_leaves_a_state_recovery_can_complete_and_the_next_start_sweeps_the_seeds() {
    if std::env::var_os("INKLKUNN_IT_CHILD").is_some() {
        return; // the child runs `child_accepts_and_blocks_in_seal`, not this test
    }
    let Some(f) = fixture("killed", Sandbox::Unconfined, true) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    f.control("block-seal");
    // The server is a child process: this test binary, run again to do one acceptance and wait in `seal`.
    let spec = serde_json::json!({
        "prikk": f.prikk, "root": f._tmp.0.join("root"), "key_dir": f.key_dir, "secret_file": f.secret_file,
        "shm": f.shm.0, "wiki": f.wiki.as_str(), "token": p.token.as_str(),
        "files": [["pages/Edit.md", "edited\n"]], "message": p.change.message,
        "expected": {
            "view": MAIN, "proposal": p.proposal.as_str(),
            "proposer_id": match &f.proposer { Actor::Account { id, .. } => id.as_str(), _ => "" },
            "proposer_name": match &f.proposer { Actor::Account { name, .. } => name.as_str(), _ => "" },
            "acceptor_id": match &f.acceptor { Actor::Account { id, .. } => id.as_str(), _ => "" },
            "acceptor_name": match &f.acceptor { Actor::Account { name, .. } => name.as_str(), _ => "" },
            "base": f.first_block,
        }
    });
    let mut child = Command::new(std::env::current_exe().unwrap())
        .args([
            "child_accepts_and_blocks_in_seal",
            "--exact",
            "--nocapture",
            "--test-threads=1",
        ])
        .env("INKLKUNN_IT_CHILD", spec.to_string())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("child");
    // Wait until the stand-in is blocked inside `seal` (the patch is committed, the seeds are on disk).
    let deadline = Instant::now() + Duration::from_secs(30);
    while !f.ctl.join("blocked-seal").exists() {
        assert!(Instant::now() < deadline, "the child never reached seal");
        std::thread::sleep(Duration::from_millis(20));
    }
    assert_eq!(
        f.seed_dirs().len(),
        1,
        "the seeds are on the tmpfs during the call"
    );
    // A start that happens now (a supervisor's second process, the command line) leaves the live call's
    // directory alone: it is held under a lock, however young or old it is.
    let pre = Fixtureless {
        root: f.root.clone(),
        key_dir: f.key_dir.clone(),
        secret_file: f.secret_file.clone(),
        shm: f.shm.0.clone(),
    };
    let beside = Signer::open(
        config(&pre, &f.prikk, Sandbox::Unconfined),
        f.ledger.clone(),
    )
    .expect("a second process starts");
    assert_eq!(beside.leftover_call_directories_removed(), 0);
    assert_eq!(f.seed_dirs().len(), 1, "a live call's seeds were swept");
    child.kill().expect("SIGKILL");
    let _ = child.wait();
    // What recovery finds: one queued patch carrying the message, nothing sealed, the seeds still on disk.
    assert_eq!(f.queue_count(), 1);
    let queued = f.prikk_json(&["status", "--format", "json"]);
    assert_eq!(
        queued
            .pointer("/queue/patches/0/message")
            .and_then(serde_json::Value::as_str),
        Some(p.change.message.as_str())
    );
    assert_eq!(f.history_len(MAIN), 1);
    assert_eq!(
        f.seed_dirs().len(),
        1,
        "SIGKILL runs no Drop: the decrypted seeds are still on the tmpfs"
    );
    // The worktree holds the written change (it matches the queued patch).
    assert_eq!(
        std::fs::read_to_string(f.repo.join("pages/Edit.md")).unwrap(),
        "edited\n"
    );
    // Recovery can complete it: `seal` alone, with the keys the kill stranded on the tmpfs (RFC 004 builds the
    // signer operation; this is the proof that the state it will meet is sealable and verifies).
    f.uncontrol("block-seal");
    let stranded = f.seed_dirs().remove(0);
    let seal = Command::new(&f.prikk)
        .args(["seal", "--allow-no-audit", "--ref", MAIN])
        .current_dir(&f.repo)
        .env(
            "PRIKK_MAINTAINER_SEED_FILE",
            stranded.join("maintainer.seed"),
        )
        .env(
            "PRIKK_MAINTAINER_KEY_ID",
            format!("inklkunn-{}-maintainer", f.wiki),
        )
        .output()
        .expect("prikk seal");
    assert!(
        seal.status.success(),
        "{}",
        String::from_utf8_lossy(&seal.stderr)
    );
    assert_eq!(f.queue_count(), 0);
    assert_eq!(f.history_len(MAIN), 2);
    assert!(
        f.storage(Sandbox::Unconfined)
            .verify(&f.repo)
            .unwrap()
            .verdict
            .ok
    );
    let history = f
        .storage(Sandbox::Unconfined)
        .history(&f.repo, &Point::View(MAIN.into()), None)
        .unwrap();
    assert_eq!(
        history
            .blocks
            .first()
            .unwrap()
            .patch_messages
            .first()
            .unwrap()
            .message,
        p.change.message
    );
    // The next start removes the seeds the kill left, at once: the kernel dropped the dead call's lock.
    let restarted = Signer::open(
        config(&pre, &f.prikk, Sandbox::Unconfined),
        f.ledger.clone(),
    )
    .expect("restart");
    assert_eq!(restarted.leftover_call_directories_removed(), 1);
    assert!(f.seed_dirs().is_empty());
    // A directory nobody holds is dead however young it is…
    let unheld = f
        .shm
        .0
        .join("inklkunn-seeds-0123456789abcdef0123456789abcdef");
    std::fs::create_dir(&unheld).unwrap();
    std::fs::write(unheld.join("author.seed"), "x").unwrap();
    // …and a half-made one (a creator that died before locking and renaming it) waits out its age first.
    let birth = f.shm.0.join(".new-0123456789abcdef0123456789abcdef");
    std::fs::create_dir(&birth).unwrap();
    let again = Signer::open(
        config(&pre, &f.prikk, Sandbox::Unconfined),
        f.ledger.clone(),
    )
    .unwrap();
    assert_eq!(again.leftover_call_directories_removed(), 1);
    assert!(!unheld.exists());
    assert!(birth.exists(), "a creator may be a moment from locking it");
}

/// The child half of the kill test: do one acceptance against the stand-in that blocks in `seal`.
#[test]
fn child_accepts_and_blocks_in_seal() {
    let Some(spec) = std::env::var_os("INKLKUNN_IT_CHILD") else {
        return; // an ordinary run of the suite: not the child
    };
    let spec: serde_json::Value = serde_json::from_str(&spec.to_string_lossy()).unwrap();
    let s = |v: &serde_json::Value| v.as_str().unwrap().to_owned();
    let ledger = Arc::new(Ledger::default());
    let e = field(&spec, "expected");
    let actor = |id: &str, name: &str| Actor::Account {
        id: AccountId::parse(id).unwrap(),
        name: DisplayName::new(name).unwrap(),
    };
    let token = AcceptanceToken::new(s(field(&spec, "token")));
    let files = field(&spec, "files")
        .as_array()
        .unwrap()
        .iter()
        .map(|f| file(f[0].as_str().unwrap(), f[1].as_str()))
        .collect();
    let change = PreparedChange {
        files,
        renames: vec![],
        message: s(field(&spec, "message")),
    };
    ledger.set(
        &token,
        ExpectedMessage {
            change_digest: change.digest(),
            wiki: WikiId::parse(&s(field(&spec, "wiki"))).unwrap(),
            view: s(field(e, "view")),
            kind: inklkunn_signer::message::Kind::Proposal,
            proposal: ProposalId::parse(&s(field(e, "proposal"))),
            proposed_by: actor(&s(field(e, "proposer_id")), &s(field(e, "proposer_name"))),
            accepted_by: actor(&s(field(e, "acceptor_id")), &s(field(e, "acceptor_name"))),
            base: BlockId::new(&s(field(e, "base"))).ok(),
            imported_from: None,
        },
    );
    let mut cfg = SignerConfig::new(
        s(field(&spec, "prikk")),
        Sandbox::Unconfined,
        RootLayout::new(s(field(&spec, "root"))),
        s(field(&spec, "key_dir")),
        s(field(&spec, "secret_file")),
        s(field(&spec, "shm")),
    );
    cfg.cheap_derivation = true;
    let signer = Signer::open_creating_store(cfg, ledger).expect("signer");
    // Blocks inside `seal` until the parent kills this process.
    let _ = signer.accept(
        &WikiId::parse(&s(field(&spec, "wiki"))).unwrap(),
        &s(field(e, "view")),
        &token,
        &change,
    );
}

#[test]
fn a_view_is_created_only_for_a_recorded_act_and_acceptances_can_target_it() {
    for (n, sandbox) in policies().into_iter().enumerate() {
        let Some(f) = fixture(&format!("view-{n}"), sandbox.clone(), false) else {
            println!("skipping: prikk not on PATH");
            return;
        };
        let act = ViewCreationAct::new("act-1");
        f.ledger.views.lock().unwrap().insert(
            "act-1".into(),
            ViewCreationFacts {
                wiki: f.wiki.clone(),
                name: "heads/draft".into(),
                from: MAIN.into(),
            },
        );
        // Not recorded; recorded for something else; malformed names.
        assert_eq!(
            f.signer.create_view(
                &f.wiki,
                "heads/draft",
                MAIN,
                &ViewCreationAct::new("unknown")
            ),
            Err(AcceptError::NotPending)
        );
        for (name, from) in [("heads/other", MAIN), ("heads/draft", "heads/other")] {
            assert_eq!(
                f.signer.create_view(&f.wiki, name, from, &act),
                Err(AcceptError::NotPending),
                "{name} {from}"
            );
        }
        assert_eq!(
            f.signer
                .create_view(&WikiId::new(), "heads/draft", MAIN, &act),
            Err(AcceptError::NotPending)
        );
        for (name, from) in [
            ("draft", MAIN),
            ("heads/draft", "main"),
            ("heads/-x", MAIN),
            ("heads/a b", MAIN),
            ("heads/draft", "remotes/heads/main"),
        ] {
            assert!(
                matches!(
                    f.signer.create_view(&f.wiki, name, from, &act),
                    Err(AcceptError::Refused(_))
                ),
                "{name} {from}"
            );
        }
        let views = |f: &Fixture| -> Vec<String> {
            f.storage(sandbox.clone())
                .views(&f.repo)
                .unwrap()
                .views
                .into_iter()
                .map(|v| v.name)
                .collect()
        };
        assert_eq!(views(&f), [MAIN]);
        // The recorded act creates the view, once.
        f.signer
            .create_view(&f.wiki, "heads/draft", MAIN, &act)
            .expect("view created");
        let mut names = views(&f);
        names.sort();
        assert_eq!(names, ["heads/draft", MAIN]);
        assert!(f.seed_dirs().is_empty());
        assert!(
            matches!(
                f.signer.create_view(&f.wiki, "heads/draft", MAIN, &act),
                Err(AcceptError::Refused(_))
            ),
            "a view exists once"
        );
        // An acceptance into the new view lands there and leaves main alone.
        let p = f.prepare(
            "heads/draft",
            vec![file("pages/Edit.md", Some("draft text\n"))],
            vec![],
        );
        f.signer
            .accept(&f.wiki, "heads/draft", &p.token, &p.change)
            .expect("accepted into the view");
        assert!(
            f.read("heads/draft", "pages/Edit.md")
                .unwrap()
                .contains("draft text")
        );
        assert!(f.read(MAIN, "pages/Edit.md").unwrap().contains("before"));
        assert_eq!(f.history_len(MAIN), 1);
        assert_eq!(f.history_len("heads/draft"), 2);
        // And back to main, which switches the worktree.
        let q = f.prepare(MAIN, vec![file("pages/Home.md", Some("home\n"))], vec![]);
        f.signer
            .accept(&f.wiki, MAIN, &q.token, &q.change)
            .expect("accepted into main");
        assert_eq!(f.history_len(MAIN), 2);
        assert!(f.storage(sandbox).verify(&f.repo).unwrap().verdict.ok);
    }
}

#[test]
fn the_unguarded_entry_creates_only_the_first_change_of_a_new_wiki() {
    let Some(f) = fixture("bootstrap", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let system = Message::system(
        Summary::from_text("More system").unwrap(),
        SystemLabel::inklkunn(),
    )
    .to_text();
    // The repository has history now: the entry that has no acceptance behind it refuses.
    std::fs::write(f.repo.join("pages/Sneaky.md"), "x\n").unwrap();
    let r = f.signer.commit_and_seal(&f.repo, &system);
    assert!(
        matches!(&r, Err(SignerError::Refused(m)) if m.contains("history")),
        "{r:?}"
    );
    assert_eq!(f.history_len(MAIN), 1);
    // Another kind of message, or no message at all, would be refused as well.
    let proposal = f.prepare(MAIN, vec![], vec![]);
    assert!(matches!(
        f.signer.commit_and_seal(&f.repo, &proposal.change.message),
        Err(SignerError::Refused(_))
    ));
    assert!(matches!(
        f.signer.commit_and_seal(&f.repo, "not a message"),
        Err(SignerError::Refused(_))
    ));
    // A directory that is not a wiki's repository is not one.
    let elsewhere = f._tmp.0.join("elsewhere");
    std::fs::create_dir_all(&elsewhere).unwrap();
    assert!(matches!(
        f.signer
            .create_repository(&elsewhere, &inklkunn_signer::KeyAuthority::for_tests()),
        Err(SignerError::Refused(_))
    ));
    assert!(matches!(
        f.signer.commit_and_seal(&elsewhere, &system),
        Err(SignerError::Refused(_))
    ));
    // A wiki that has keys does not get a second pair.
    assert!(matches!(
        f.signer
            .create_repository(&f.repo, &inklkunn_signer::KeyAuthority::for_tests()),
        Err(SignerError::Refused(_))
    ));
    // Key status says ids and dates and nothing else.
    let status = f.signer.key_status(&f.wiki).unwrap();
    assert_eq!(status.generation, 1);
    assert_eq!(status.author_key_id, format!("inklkunn-{}-author", f.wiki));
    assert_eq!(status.rotated_at, None);
}

#[test]
fn opening_the_signer_checks_the_secret_and_the_tmpfs() {
    let Some(f) = fixture("open", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let pre = Fixtureless {
        root: f.root.clone(),
        key_dir: f.key_dir.clone(),
        secret_file: f.secret_file.clone(),
        shm: f.shm.0.clone(),
    };
    // The wrong secret is reported at open, not at the first signature.
    let wrong = f._tmp.0.join("wrong-secret");
    std::fs::write(&wrong, "a different operator secret, also long enough").unwrap();
    let mut cfg = config(&pre, &f.prikk, Sandbox::Unconfined);
    cfg.secret_file = wrong;
    let r = Signer::open_creating_store(cfg, f.ledger.clone());
    assert!(
        matches!(&r, Err(SignerError::Unavailable(m)) if m.contains("does not open the key store")),
        "{:?}",
        r.err()
    );
    // A seed directory that is not a tmpfs is refused.
    let mut cfg = config(&pre, &f.prikk, Sandbox::Unconfined);
    cfg.tmpfs_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let on_disk = Signer::open_creating_store(cfg, f.ledger.clone());
    let mountinfo = std::fs::read_to_string("/proc/self/mountinfo").unwrap();
    if !mountinfo.lines().any(|l| {
        l.contains(" tmpfs ")
            && env!("CARGO_MANIFEST_DIR")
                .starts_with(l.split(' ').nth(4).unwrap_or("/nonexistent/"))
    }) {
        assert!(
            matches!(&on_disk, Err(SignerError::Unavailable(m)) if m.contains("tmpfs")),
            "{:?}",
            on_disk.err()
        );
    }
}

#[test]
fn after_a_retirement_every_acceptance_is_sealed_but_cannot_be_confirmed_until_prikk_can_verify_it()
{
    // Ledger PK-34: removing a maintainer key from trust makes what it sealed unverifiable, so the verify that
    // closes every acceptance fails. The change IS sealed and the error says which block, which is what an
    // orchestrator needs to record it instead of retrying. When prikk keeps a retired key's history
    // verifiable this test fails and the runbook and the ledger row are due a change.
    let Some(f) = fixture("retired", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    f.signer
        .rotate_keys(
            &inklkunn_signer::KeyAuthority::for_tests(),
            &f.repo,
            inklkunn_signer::OldKey::Retire,
        )
        .expect("rotation");
    let before = f.history_len(MAIN);
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    let r = f.signer.accept(&f.wiki, MAIN, &p.token, &p.change);
    let Err(AcceptError::SealedUnconfirmed {
        sealed: Some(sealed),
        why: Unconfirmed::VerifyFailed,
        ..
    }) = &r
    else {
        panic!("expected a sealed change that did not verify: {r:?}");
    };
    assert_eq!(f.history_len(MAIN), before + 1);
    assert_eq!(f.tip_block(MAIN), sealed.block_id);
    assert_eq!(f.queue_count(), 0);
}

#[test]
fn two_acceptances_at_once_on_one_wiki_never_interleave() {
    // Without a lock per wiki this failed in about half the runs: both threads wrote their files into one
    // worktree, one committed both, and one acceptance's message was signed over the other's unaccepted
    // file. With it, whichever comes second waits, and each block carries only its own change.
    let Some(f) = fixture("concurrent", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let before = f.history_len(MAIN);
    for round in 0..8 {
        let a = f.prepare(
            MAIN,
            vec![file("pages/Edit.md", Some(&format!("edit {round}\n")))],
            vec![],
        );
        let b = f.prepare(
            MAIN,
            vec![file("pages/Home.md", Some(&format!("home {round}\n")))],
            vec![],
        );
        let (ra, rb) = std::thread::scope(|s| {
            let ta = s.spawn(|| f.signer.accept(&f.wiki, MAIN, &a.token, &a.change));
            let tb = s.spawn(|| f.signer.accept(&f.wiki, MAIN, &b.token, &b.change));
            (ta.join().unwrap(), tb.join().unwrap())
        });
        let (ra, rb) = (ra.expect("the first"), rb.expect("the second"));
        assert_ne!(
            ra.block_id, rb.block_id,
            "round {round}: two acceptances are two blocks"
        );
        assert_eq!(f.queue_count(), 0, "round {round}");
    }
    assert_eq!(f.history_len(MAIN), before + 16);
    assert!(f.read(MAIN, "pages/Edit.md").unwrap().contains("edit 7"));
    assert!(f.read(MAIN, "pages/Home.md").unwrap().contains("home 7"));
}

/// Another process holding the wiki's write lock: a shell opens the lock file on descriptor 9, locks it with
/// util-linux `flock 9`, records its process id, and *becomes* `sleep`, so the process that holds the lock is the
/// one the test kills.
struct OtherProcess {
    child: std::process::Child,
}

impl OtherProcess {
    fn holding(lock_file: &Path) -> Option<OtherProcess> {
        if Command::new("flock").arg("--version").output().is_err() {
            println!("skipping: flock(1) not available");
            return None;
        }
        let child = Command::new("sh")
            .args([
                "-c",
                "exec 9<>\"$0\" && flock 9 && echo $$ > \"$0\" && exec sleep 60",
            ])
            .arg(lock_file)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .ok()?;
        let started = Instant::now();
        // The pid appears in the file once the child has the lock.
        while std::fs::read_to_string(lock_file)
            .ok()
            .and_then(|t| t.trim().parse::<u32>().ok())
            != Some(child.id())
        {
            assert!(
                started.elapsed() < Duration::from_secs(10),
                "the holder never locked"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        Some(OtherProcess { child })
    }

    fn pid(&self) -> u32 {
        self.child.id()
    }

    fn kill(mut self) {
        self.child.kill().unwrap();
        self.child.wait().unwrap();
    }
}

impl Drop for OtherProcess {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[test]
fn a_wiki_written_by_another_process_is_busy_by_name_and_free_again_when_its_holder_dies() {
    let Some(f) = fixture("busy", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let Some(other) = OtherProcess::holding(&f.root.lock_file(&f.wiki)) else {
        return;
    };
    let pid = other.pid();
    let before = f.history_len(MAIN);
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    // An acceptance, a view creation, key work and the first change: each is refused at once and names the holder.
    let started = Instant::now();
    assert_eq!(
        f.signer.accept(&f.wiki, MAIN, &p.token, &p.change),
        Err(AcceptError::Busy { holder: Some(pid) })
    );
    f.ledger.views.lock().unwrap().insert(
        "act-busy".into(),
        ViewCreationFacts {
            wiki: f.wiki.clone(),
            name: "heads/draft".into(),
            from: MAIN.into(),
        },
    );
    assert_eq!(
        f.signer.create_view(
            &f.wiki,
            "heads/draft",
            MAIN,
            &ViewCreationAct::new("act-busy")
        ),
        Err(AcceptError::Busy { holder: Some(pid) })
    );
    for r in [
        f.signer
            .rotate_keys(
                &inklkunn_signer::KeyAuthority::for_tests(),
                &f.repo,
                inklkunn_signer::OldKey::Keep,
            )
            .map(|_| ()),
        f.signer
            .create_keys(&inklkunn_signer::KeyAuthority::for_tests(), &f.repo)
            .map(|_| ()),
        f.signer.commit_and_seal(&f.repo, "x").map(|_| ()),
    ] {
        assert!(
            matches!(&r, Err(SignerError::Busy { holder: Some(h), .. }) if *h == pid),
            "{r:?}"
        );
    }
    assert!(
        started.elapsed() < Duration::from_secs(10),
        "busy is an answer, not a wait"
    );
    let shown = f
        .signer
        .accept(&f.wiki, MAIN, &p.token, &p.change)
        .unwrap_err()
        .to_string();
    assert!(shown.contains(&pid.to_string()), "{shown}");
    // Nothing changed: no queue, no new block, the page as it was, no seed left behind.
    assert_eq!(f.queue_count(), 0);
    assert_eq!(f.history_len(MAIN), before);
    assert!(f.seed_dirs().is_empty());
    // The holder dies; the kernel drops its lock; the same acceptance goes through.
    other.kill();
    f.signer
        .accept(&f.wiki, MAIN, &p.token, &p.change)
        .expect("free again");
    assert_eq!(f.history_len(MAIN), before + 1);
}

#[test]
fn the_lock_file_is_beside_the_repository_and_never_inside_it() {
    let Some(f) = fixture("lockplace", Sandbox::Unconfined, false) else {
        println!("skipping: prikk not on PATH");
        return;
    };
    let p = f.prepare(MAIN, vec![file("pages/Edit.md", Some("edited\n"))], vec![]);
    f.signer.accept(&f.wiki, MAIN, &p.token, &p.change).unwrap();
    let lock = f.root.lock_file(&f.wiki);
    assert!(lock.is_file());
    assert!(!lock.starts_with(&f.repo));
    assert_eq!(lock.parent(), f.repo.parent());
    // Nothing of it reached the repository: the worktree is clean and the store holds no lock file of ours.
    assert!(
        !std::fs::read_dir(&f.repo)
            .unwrap()
            .flatten()
            .any(|e| e.file_name().to_string_lossy().ends_with(".lock"))
    );
}
